        long ans = 0;
        long cur = nums[0];
        for (int i = 1; i < nums.length; i++) {
            long x = nums[i];
            if (x % cur != 0) cur = (x / cur + 1) * cur;
            else cur = x;
            ans += cur - x;
        }
        return ans;
    }
}

