class Solution {
    public long minOperations(int[] nums) {
        final int V = 6000;
        final long INF = Long.MAX_VALUE / 2;
        long[] dp = new long[V + 1];
        Arrays.fill(dp, INF);
        for (int v = nums[0]; v <= V; v++) dp[v] = v - nums[0];
        for (int i = 1; i < nums.length; i++) {
            long[] ndp = new long[V + 1];
            Arrays.fill(ndp, INF);
            for (int u = 1; u <= V; u++) {
                if (dp[u] >= INF) continue;
                for (int v = u; v <= V; v += u)
                    if (v >= nums[i])
                        ndp[v] = Math.min(ndp[v], dp[u] + v - nums[i]);
            }
            dp = ndp;
        }
        long ans = INF;
        for (long x : dp) ans = Math.min(ans, x);
        return ans;
    }
}

